  function weightedSampleCardsForOffers(cards, count2, rng2, lootLuck, source, currentBiome, context) {
    if (count2 <= 0 || cards.length === 0) return [];
    const pool = [...cards].filter(
      (card) => getCardOfferWeight(card, lootLuck, source, currentBiome, context) > 0
    );
    if (pool.length === 0) return [];
    const picks = [];
    while (pool.length > 0 && picks.length < count2) {
      const picked = weightedPickByOfferWeight(
        pool,
        lootLuck,
        source,
        rng2,
        currentBiome,
        context
      );
      picks.push(picked);
      const index2 = pool.indexOf(picked);
      if (index2 >= 0) pool.splice(index2, 1);
    }
    return picks;
  }

  // src/game/engine/rewards.ts
  function markCardAcquiredForRunConditionUnlock(runState, definitionId) {
    const resourceKey = getRunConditionCardLootUnlockResourceKey(definitionId);
    return {
      ...runState,
      earnedResources: {
        ...runState.earnedResources,
        [resourceKey]: (runState.earnedResources?.[resourceKey] ?? 0) + 1
      }
    };
  }
  function addCardToRunDeck(runState, definitionId) {
    const newCard = {
      instanceId: nanoid(),
      definitionId,
      upgraded: false
    };
    const hpPenalty = runState.relicIds.includes("love_void_compass") ? 2 : 0;
    const nextState = {
      ...runState,
      deck: [...runState.deck, newCard],
      playerCurrentHp: Math.max(1, runState.playerCurrentHp - hpPenalty)
    };
    return markCardAcquiredForRunConditionUnlock(nextState, definitionId);
  }

