    const drawPileIndex = findFirstInkedCardIndex(combat2.drawPile, cardDefs3);
    if (drawPileIndex >= 0) {
      const inkedCard = combat2.drawPile[drawPileIndex];
      const replaceHandIndex = Math.max(
        0,
        combat2.hand.findIndex((card) => !hasInkedVariant(card, cardDefs3))
      );
      if (combat2.hand.length === 0) {
        return {
          ...combat2,
          hand: [inkedCard],
          drawPile: combat2.drawPile.filter((_, index2) => index2 !== drawPileIndex)
        };
      }
      const displacedCard = combat2.hand[replaceHandIndex];
      const nextHand = [...combat2.hand];
      nextHand[replaceHandIndex] = inkedCard;
      const nextDrawPile = [...combat2.drawPile];
      nextDrawPile[drawPileIndex] = displacedCard;
      return {
        ...combat2,
        hand: nextHand,
        drawPile: nextDrawPile
      };
    }
